    contributions: () => data13 ? groupDigits(data13.yearTotal) : "",
    project: projectName2,
    repo: () => pi?.repo || pd?.fullName || "",
    tagline: () => pi?.tagline || pd?.description || "",
    version,
    license: () => pd?.license || "",
    forks: () => pd ? groupDigits(pd.forks) : "",
