function fillOutsideCode(text, fill2) {
  return text.split(/(^(?:```|~~~)[^\n]*\n[\s\S]*?^(?:```|~~~)[ \t]*$)/m).map((part, i) => i % 2 === 1 ? part : part.split(/(`+[^`]*?`+)/).map((p, j) => j % 2 === 1 ? p : fill2(p)).join("")).join("");
}

