var W24 = 840;
function quoteMarks(color, x, y, s, cls = "") {
  const one = (ox) => `<circle cx="${n1(ox + 9 * s)}" cy="${n1(y + 24 * s)}" r="${n1(9 * s)}" fill="${color}"/><path d="M${n1(ox + 0.6 * s)} ${n1(y + 24 * s)}C${n1(ox + 0.6 * s)} ${n1(y + 11 * s)} ${n1(ox + 7 * s)} ${n1(y + 3 * s)} ${n1(ox + 17 * s)} ${n1(y + 0.5 * s)}" stroke="${color}" stroke-width="${n1(5.2 * s)}" stroke-linecap="round" fill="none"/>`;
  return `<g class="${cls}">${one(x)}${one(x + 25 * s)}</g>`;
}
function layoutQuotes(t, raw, maxW) {
  const opts = { heading: true };
  for (const size of [28, 26, 24, 22, 20, 18]) {
    const qs = raw.map((q) => ({ ...q, lines: wrapText(t, q.text, size, maxW, 99, opts) }));
    if (qs.every((q) => q.lines.length <= 3)) return { size, quotes: qs };
  }
  return { size: 18, quotes: raw.map((q) => ({ ...q, lines: wrapText(t, q.text, 18, maxW, 4, opts) })) };
}
