    const k = 1 / 6;
    const c1x = p1[0] + (p2[0] - p0[0]) * k;
    const c1y = c(p1[1] + (p2[1] - p0[1]) * k);
    const c2x = p2[0] - (p3[0] - p1[0]) * k;
    const c2y = c(p2[1] - (p3[1] - p1[1]) * k);
    d += `C${f(c1x)} ${f(c1y)} ${f(c2x)} ${f(c2y)} ${f(p2[0])} ${f(p2[1])}`;
