    jsx: "ts",
    mjs: "ts",
    cjs: "ts",
    mts: "ts",
    cts: "ts",
    py: "python",
    pyi: "python",
    rs: "rust",
    go: "go",
    sh: "shell",
    bash: "shell",
    zsh: "shell",
    fish: "shell",
    json: "json",
